using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text.Json.Nodes;
using DispatchPro.Api.Domain;
using DispatchPro.Api.Infrastructure;
using DispatchPro.Api.Services;
using Microsoft.AspNetCore.TestHost;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using Microsoft.Extensions.Hosting;
using Npgsql;
using Xunit;
namespace DispatchPro.Tests;
public sealed class RideCallTests
{
    static RideCallState Ring(DateTimeOffset now)=>new(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),true,Guid.NewGuid(),null,null,"ringing",now,null,now.AddSeconds(40),1);
    [Fact] public void PushAnswerCancelsOtherDeviceRingingWithoutPushingHeartbeats(){var ring=Ring(DateTimeOffset.UtcNow);Assert.True(RideCalls.NotifyTransition(ring));Assert.True(RideCalls.NotifyTransition(ring with{State="active",Revision=2}));Assert.False(RideCalls.NotifyTransition(ring with{State="active",Revision=3}));Assert.False(RideCalls.NotifyTransition(ring with{State="ringing",Revision=3}));foreach(var state in new[]{"ended","rejected","expired"})Assert.True(RideCalls.NotifyTransition(ring with{State=state,Revision=4}));}
    [Fact] public void StateTransitionsExpireAndRequireBothHeartbeats(){var now=DateTimeOffset.UtcNow;var ring=Ring(now);Assert.Throws<InvalidOperationException>(()=>RideCalls.Transition(ring,"answer",true,Guid.NewGuid(),Guid.NewGuid(),now));var active=RideCalls.Transition(ring,"answer",false,Guid.NewGuid(),Guid.NewGuid(),now);Assert.Equal("active",active.State);var heartbeat=RideCalls.Transition(active,"heartbeat",true,ring.CallerActor,ring.CallerDevice,now.AddSeconds(30));Assert.Equal(now.AddSeconds(65),heartbeat.ExpiresAt);Assert.False(RideCalls.Live(heartbeat,now.AddSeconds(66)));Assert.Equal("expired",RideCalls.Transition(heartbeat,"heartbeat",true,ring.CallerActor,ring.CallerDevice,now.AddSeconds(66)).State);Assert.Equal("ended",RideCalls.Transition(active,"end",true,ring.CallerActor,ring.CallerDevice,now).State);Assert.Equal("rejected",RideCalls.Transition(ring,"reject",false,Guid.NewGuid(),Guid.NewGuid(),now).State);}
    [Fact] public void TerminalRideAndWrongDeviceCannotOwnMedia(){foreach(var status in new[]{RideStatus.Assigned,RideStatus.Completed,RideStatus.Cancelled,RideStatus.Rejected})Assert.False(RideCalls.AllowedStatus(status));var ring=Ring(DateTimeOffset.UtcNow);Assert.True(RideCalls.OwnsDevice(ring,true,ring.CallerActor,ring.CallerDevice));Assert.False(RideCalls.OwnsDevice(ring,true,ring.CallerActor,Guid.NewGuid()));Assert.False(RideCalls.OwnsDevice(ring,true,Guid.NewGuid(),ring.CallerDevice));}
    [Fact] public void SignalingIsDedupeAndTenantDeviceIsolated(){var signals=new RideCallSignals(TimeProvider.System);var tenant=Guid.NewGuid();var call=Guid.NewGuid();var device=Guid.NewGuid();var message=new RideCallSignal(Guid.NewGuid(),device,"ice","{}",DateTimeOffset.UtcNow);signals.Add(tenant,call,message);signals.Add(tenant,call,message);Assert.Single(signals.Read(tenant,call,Guid.NewGuid()));Assert.Empty(signals.Read(Guid.NewGuid(),call,Guid.NewGuid()));Assert.Empty(signals.Read(tenant,call,device));signals.End(tenant,call);Assert.Empty(signals.Read(tenant,call,Guid.NewGuid()));}
    [Fact] public async Task AnonymousCallAndMobileRoutesFailBeforeDatabase(){await using var factory=new ApiFactory("Host=127.0.0.1;Port=1;Database=not_contacted;Timeout=1");using var client=factory.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await client.PostAsJsonAsync("/api/v1/driver/calls",new{rideId=Guid.NewGuid(),deviceId=Guid.NewGuid(),requestId=Guid.NewGuid()})).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await client.GetAsync("/api/v1/customer-app/mobile/updates?deviceId="+Guid.NewGuid())).StatusCode);}
    static async Task<JsonNode> Json(HttpResponseMessage response){var body=await response.Content.ReadAsStringAsync();Assert.True(response.IsSuccessStatusCode,$"{response.StatusCode}: {body}");return string.IsNullOrWhiteSpace(body)?new JsonObject():JsonNode.Parse(body)!;}
    [PostgresFact] public async Task AuthorizedCallMultipleDevicesChatUnreadAndLifecycle()
    {
        var adminConnection=Environment.GetEnvironmentVariable("TAXI_TEST_POSTGRES")!;var name="ride_calls_"+Guid.NewGuid().ToString("N");await using var admin=new NpgsqlConnection(adminConnection);await admin.OpenAsync();await using(var create=new NpgsqlCommand($"CREATE DATABASE {name}",admin))await create.ExecuteNonQueryAsync();
        try{
            await using var baseFactory=new ApiFactory(new NpgsqlConnectionStringBuilder(adminConnection){Database=name}.ConnectionString);await using var factory=baseFactory.WithWebHostBuilder(b=>b.ConfigureTestServices(s=>s.RemoveAll<IHostedService>()));
            const string slug="call-test";const string password="Call-test-password-123!";
            using(var scope=factory.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<TaxiDb>();await db.Database.MigrateAsync();await Seed.RunAsync(db,scope.ServiceProvider.GetRequiredService<TenantContext>(),new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Seed:TenantSlug",slug},{"Seed:AdminPassword",password}}).Build());}
            using var customer=factory.CreateClient();using var other=factory.CreateClient();using var driver=factory.CreateClient();using var office=factory.CreateClient();var account=Guid.NewGuid();var secret=new string('a',64);
            var registration=await Json(await customer.VerifiedRegistration(new{tenant=slug,accountId=account,deviceSecret=secret,fullName="Customer",phone="0591234567"}));customer.DefaultRequestHeaders.Authorization=new("Bearer",registration["accessToken"]!.GetValue<string>());
            var outsider=await Json(await other.VerifiedRegistration(new{tenant=slug,accountId=Guid.NewGuid(),deviceSecret=secret,fullName="Other",phone="0591234568"}));other.DefaultRequestHeaders.Authorization=new("Bearer",outsider["accessToken"]!.GetValue<string>());
            var login=await Json(await office.PostAsJsonAsync("/api/v1/auth/login",new{tenant=slug,username="admin",password}));office.DefaultRequestHeaders.Authorization=new("Bearer",login["accessToken"]!.GetValue<string>());
            var rideId=Guid.NewGuid();Guid driverId;
            using(var scope=factory.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<TaxiDb>();var tenant=scope.ServiceProvider.GetRequiredService<TenantContext>();tenant.TenantId=await db.Set<Tenant>().Where(t=>t.Slug==slug).Select(t=>t.Id).SingleAsync();tenant.ActorId=account;var role=await db.Set<Role>().SingleAsync(r=>r.Name=="Driver");var user=new User{RoleId=role.Id,Username="driver"};user.PasswordHash=new Microsoft.AspNetCore.Identity.PasswordHasher<User>().HashPassword(user,password);db.Add(user);var d=new Driver{UserId=user.Id,FullName="Driver",Status=DriverStatus.Busy};db.Add(d);driverId=d.Id;var request=new RideRequest{CustomerId=account,Pickup="pickup",Destination="destination",Source="CUSTOMER_APP"};db.Add(request);db.Add(new Ride{Id=rideId,RideRequestId=request.Id,DriverId=d.Id,Status=RideStatus.Accepted});await db.SaveChangesAsync();driver.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",scope.ServiceProvider.GetRequiredService<TokenService>().Issue(user));}
            var callerDevice=Guid.NewGuid();var answerDevice=Guid.NewGuid();var otherDevice=Guid.NewGuid();var callId=Guid.NewGuid();var createCall=new{rideId,deviceId=callerDevice,requestId=callId};
            Assert.Equal(HttpStatusCode.Forbidden,(await other.PostAsJsonAsync("/api/v1/customer-app/calls",createCall)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await office.PostAsJsonAsync("/api/v1/driver/calls",createCall)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await customer.PostAsJsonAsync("/api/v1/driver/calls",createCall)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await driver.PostAsJsonAsync("/api/v1/customer-app/calls",createCall)).StatusCode);
            var created=await Json(await customer.PostAsJsonAsync("/api/v1/customer-app/calls",createCall));Assert.Equal("ringing",created["state"]!.GetValue<string>());callId=created["id"]!.GetValue<Guid>();Assert.NotEqual(createCall.requestId,callId);await Json(await customer.PostAsJsonAsync("/api/v1/customer-app/calls",createCall));Assert.Equal(HttpStatusCode.Conflict,(await customer.PostAsJsonAsync("/api/v1/customer-app/calls",new{rideId,deviceId=callerDevice,requestId=Guid.NewGuid()})).StatusCode);
            Assert.Equal(HttpStatusCode.Conflict,(await customer.PostAsJsonAsync($"/api/v1/customer-app/calls/{callId}/answer",new{deviceId=callerDevice})).StatusCode);
            var answers=await Task.WhenAll(driver.PostAsJsonAsync($"/api/v1/driver/calls/{callId}/answer",new{deviceId=answerDevice}),driver.PostAsJsonAsync($"/api/v1/driver/calls/{callId}/answer",new{deviceId=otherDevice}));Assert.Single(answers,a=>a.StatusCode==HttpStatusCode.OK);Assert.Single(answers,a=>a.StatusCode==HttpStatusCode.Conflict);var winner=answers[0].StatusCode==HttpStatusCode.OK?answerDevice:otherDevice;var loser=winner==answerDevice?otherDevice:answerDevice;
            Assert.Equal(HttpStatusCode.Conflict,(await driver.PostAsJsonAsync($"/api/v1/driver/calls/{callId}/signal",new{deviceId=loser,id=Guid.NewGuid(),kind="ice",data="{}"})).StatusCode);
            await Json(await customer.PostAsJsonAsync($"/api/v1/customer-app/calls/{callId}/signal",new{deviceId=callerDevice,id=Guid.NewGuid(),kind="offer",data="{\"type\":\"offer\",\"sdp\":\"test-only\"}"}));
            var snapshot=await Json(await driver.GetAsync("/api/v1/driver/mobile/updates?deviceId="+winner));Assert.Single(snapshot["data"]!["calls"]!.AsArray());Assert.Single(snapshot["data"]!["signals"]!.AsArray());Assert.Empty((await Json(await driver.GetAsync("/api/v1/driver/mobile/updates?deviceId="+loser)))["data"]!["signals"]!.AsArray());Assert.Empty((await Json(await other.GetAsync("/api/v1/customer-app/mobile/updates?deviceId="+Guid.NewGuid())))["data"]!["calls"]!.AsArray());
            var messageId=Guid.NewGuid();await Json(await customer.PostAsJsonAsync($"/api/v1/customer-app/rides/{rideId}/chat",new{id=messageId,text="hello driver"}));snapshot=await Json(await driver.GetAsync("/api/v1/driver/mobile/updates?deviceId="+winner));Assert.Equal(1,snapshot["data"]!["unread"]![rideId.ToString()]!.GetValue<int>());Assert.Equal("hello driver",Assert.Single(snapshot["data"]!["chat"]!.AsArray())!["text"]!.GetValue<string>());await Json(await driver.PostAsJsonAsync("/api/v1/driver/mobile/chat-read",new{rideId,messageId}));snapshot=await Json(await driver.GetAsync("/api/v1/driver/mobile/updates?deviceId="+winner));Assert.Equal(0,snapshot["data"]!["unread"]![rideId.ToString()]!.GetValue<int>());
            Assert.Equal(HttpStatusCode.Conflict,(await driver.PostAsJsonAsync($"/api/v1/driver/calls/{callId}/end",new{deviceId=loser})).StatusCode);Assert.Equal("ended",(await Json(await driver.PostAsJsonAsync($"/api/v1/driver/calls/{callId}/end",new{deviceId=winner})))["state"]!.GetValue<string>());
            var rejectId=Guid.NewGuid();rejectId=(await Json(await driver.PostAsJsonAsync("/api/v1/driver/calls",new{rideId,deviceId=winner,requestId=rejectId})))["id"]!.GetValue<Guid>();Assert.Equal("rejected",(await Json(await customer.PostAsJsonAsync($"/api/v1/customer-app/calls/{rejectId}/reject",new{deviceId=callerDevice})))["state"]!.GetValue<string>());
            var outgoing=await Json(await driver.PostAsJsonAsync("/api/v1/driver/calls",new{rideId,deviceId=winner,requestId=Guid.NewGuid()}));
            var outgoingId=outgoing["id"]!.GetValue<Guid>();Assert.Equal("ringing",outgoing["state"]!.GetValue<string>());
            var incoming=await Json(await customer.GetAsync("/api/v1/customer-app/mobile/updates?deviceId="+callerDevice));
            var incomingCall=incoming["data"]!["calls"]!.AsArray().Single(c=>c!["id"]!.GetValue<Guid>()==outgoingId)!;
            Assert.False(incomingCall["caller"]!.GetValue<bool>());Assert.Equal("Driver",incomingCall["peerName"]!.GetValue<string>());
            Assert.Equal("active",(await Json(await customer.PostAsJsonAsync($"/api/v1/customer-app/calls/{outgoingId}/answer",new{deviceId=callerDevice})))["state"]!.GetValue<string>());
            Assert.Equal("active",(await Json(await driver.GetAsync($"/api/v1/driver/calls/{outgoingId}?deviceId={winner}")))["call"]!["state"]!.GetValue<string>());
            Assert.Equal("ended",(await Json(await customer.PostAsJsonAsync($"/api/v1/customer-app/calls/{outgoingId}/end",new{deviceId=callerDevice})))["state"]!.GetValue<string>());
            Assert.Equal("ended",(await Json(await driver.GetAsync($"/api/v1/driver/calls/{outgoingId}?deviceId={winner}")))["call"]!["state"]!.GetValue<string>());
            using(var scope=factory.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<TaxiDb>();var tenant=scope.ServiceProvider.GetRequiredService<TenantContext>();tenant.TenantId=await db.Set<Tenant>().Where(t=>t.Slug==slug).Select(t=>t.Id).SingleAsync();tenant.ActorId=account;var ride=await db.Set<Ride>().SingleAsync(r=>r.Id==rideId);Assert.Equal(driverId,ride.DriverId);ride.Status=RideStatus.Completed;await db.SaveChangesAsync();}
            Assert.Equal(HttpStatusCode.Forbidden,(await customer.PostAsJsonAsync("/api/v1/customer-app/calls",new{rideId,deviceId=callerDevice,requestId=Guid.NewGuid()})).StatusCode);
        }finally{await using var drop=new NpgsqlCommand($"DROP DATABASE {name} WITH (FORCE)",admin);await drop.ExecuteNonQueryAsync();}
    }
}
